    # Iterate over each subsequent row
    for _ in range(1, n):
        curr = [1, 1]
        for j in range(1, m):
            curr.append((curr[-1] + curr[-2] + prev[j] + prev[j-1]) % MOD)
        prev = curr

    return sum(prev) % MOD

