def count_random_pictures(n, m):
    if m == 1:
        return 2 ** n % MOD

    # dp[i][j] will store the number of ways to color the first i rows
    # with the j-th pattern of the previous row
    dp = [[0] * (1 << m) for _ in range(n)]

    # Initialize the first row
    for mask in range(1 << m):
        if is_valid(mask):
            dp[0][mask] = 1

    # Fill the dp table
    for i in range(1, n):
        for prev_mask in range(1 << m):
            if is_valid(prev_mask):
                for curr_mask in range(1 << m):
                    if is_valid(curr_mask) and is_compatible(prev_mask, curr_mask):
                        dp[i][curr_mask] = (dp[i][curr_mask] + dp[i-1][prev_mask]) % MOD

    # Sum up all valid configurations for the last row
    result = sum(dp[n-1]) % MOD
    return result

def is_valid(mask):
    # Check if the mask represents a valid row (no two adjacent cells have the same color)
    for j in range(m):
        if (mask & (1 << j)) > 0 and ((j > 0 and (mask & (1 << (j-1))) > 0) or (j < m-1 and (mask & (1 << (j+1))) > 0)):
            return False
    return True

def is_compatible(prev_mask, curr_mask):
    # Check if the current mask is compatible with the previous mask (no two adjacent cells in the same column have the same color)
    for j in range(m):
        if (prev_mask & (1 << j)) > 0 and (curr_mask & (1 << j)) > 0:
            return False
    return True

